import { GWidget } from "./GWidget";
import { Tween } from "../tween/Tween";
import { ProgressTitleType } from "./Const";
import { ILaya } from "../../ILaya";
import { MathUtil } from "../maths/MathUtil";
import { NodeFlags } from "../Const";
import { GImage } from "./GImage";
import { GLoader } from "./GLoader";
import { ProgressMesh } from "../display/mesh/ProgressMesh";

/**
 * @en GProgressBar is a widget that displays a progress bar.
 * @zh GProgressBar 是一个显示进度条的小部件。
 * @blueprintInheritable
 */
export class GProgressBar extends GWidget {
    private _hBar: GWidget;
    private _vBar: GWidget;
    private _titleWidget: GWidget;

    private _min: number = 0;
    private _max: number = 0;
    private _value: number = 0;
    private _titleType: ProgressTitleType = 0;
    private _reverse: boolean = false;

    private _barMaxWidthDelta: number = 0;
    private _barMaxHeightDelta: number = 0;
    private _barStartX: number = 0;
    private _barStartY: number = 0;

    private _tween: Tween;

    constructor() {
        super();

        this._value = 50;
        this._max = 100;
    }

    /**
     * @en The type of title displayed on the progress bar.
     * @zh 进度条上显示的标题类型。
     */
    get titleType(): ProgressTitleType {
        return this._titleType;
    }

    set titleType(value: ProgressTitleType) {
        if (this._titleType != value) {
            this._titleType = value;
            this.update(null, true);
        }
    }

    /**
     * @en Minimum value of the progress bar.
     * @zh 进度条的最小值。
     */
    get min(): number {
        return this._min;
    }

    set min(value: number) {
        if (this._min != value) {
            this._min = value;
            this.update(null, true);
        }
    }

    /**
     * @en Maximum value of the progress bar.
     * @zh 进度条的最大值。
     */
    get max(): number {
        return this._max;
    }

    set max(value: number) {
        if (this._max != value) {
            this._max = value;
            this.update(null, true);
        }
    }

    /**
     * @en Current value of the progress bar.
     * @zh 进度条的当前值。
     */
    get value(): number {
        return this._value;
    }

    set value(value: number) {
        if (this._value != value) {
            if (this._tween) {
                this._tween.kill();
                this._tween = null;
            }

            this._value = value;
            this.update(null, true);
        }
    }

    /**
     * @en The horizontal bar component of the progress bar.
     * @zh 进度条的水平条组件。
     */
    get hBar(): GWidget {
        return this._hBar;
    }

    set hBar(value: GWidget) {
        this._hBar = value;
        this._value = this._max;
        this._barStartX = 0;
        this.update(null, false);
    }

    /**
     * @en The vertical bar component of the progress bar.
     * @zh 进度条的垂直条组件。
     */
    get vBar(): GWidget {
        return this._vBar;
    }

    set vBar(value: GWidget) {
        this._vBar = value;
        this._value = this._max;
        this._barStartY = 0;
        this.update(null, false);
    }

    /**
     * @en The title component of the progress bar.
     * @zh 进度条的标题组件。
     */
    get titleWidget(): GWidget {
        return this._titleWidget;
    }

    set titleWidget(value: GWidget) {
        this._titleWidget = value;
        this.update(null, false);
    }

    /**
     * @en Indicates whether the progress bar is reversed.
     * @zh 指示进度条是否为反向。
     */
    get reverse(): boolean {
        return this._reverse;
    }

    set reverse(value: boolean) {
        this._reverse = value;
        this.update(null, false);
    }

    /**
     * @en Tweens the value of the progress bar to a target value over a specified duration.
     * @param value The target value to tween to.
     * @param duration The duration of the tween in milliseconds.
     * @return Returns a Tween instance that can be used to control the tween animation.
     * @zh 使用缓动改变进度条的值。
     * @param value 目标值。 
     * @param duration 缓动持续时间（毫秒）。 
     * @return 返回一个 Tween 实例，可以用于控制缓动动画。 
     */
    tweenValue(value: number, duration: number): Tween {
        let oldValule: number;

        if (this._tween) {
            let tweener = this._tween.findTweener("progress");
            if (tweener)
                oldValule = tweener.value.get(null);
            else
                oldValule = this._value;
            tweener.kill();
        }
        else
            oldValule = this._value;

        this._value = value;
        return Tween.create(this).name("progress").go(null, oldValule, this._value).duration(duration).ease("linear")
            .onUpdate(tweener => this.update(tweener.value.get(null)));
    }

    protected update(newValue: number, delay?: boolean): void {
        if (this._getBit(NodeFlags.EDITING_ROOT_NODE)) {
            this.updateTitle(this._max, this._max, 1);
            return;
        }

        if (newValue == null && delay === true) {
            ILaya.timer.callLater(this, this.update);
            return;
        }

        if (newValue == null)
            newValue = this._value;
        let percent = MathUtil.clamp01((newValue - this._min) / (this._max - this._min));

        this.updateTitle(newValue, this._max, percent);

        let fullWidth = this.width - this._barMaxWidthDelta;
        let fullHeight = this.height - this._barMaxHeightDelta;
        if (!this._reverse) {
            if (this._hBar) {
                if (!this.setFillAmount(this._hBar, percent))
                    this._hBar.width = Math.round(fullWidth * percent);
            }
            if (this._vBar) {
                if (!this.setFillAmount(this._vBar, percent))
                    this._vBar.height = Math.round(fullHeight * percent);
            }
        }
        else {
            if (this._hBar) {
                if (!this.setFillAmount(this._hBar, 1 - percent)) {
                    this._hBar.width = Math.round(fullWidth * percent);
                    this._hBar.x = this._barStartX + (fullWidth - this._hBar.width);
                }

            }
            if (this._vBar) {
                if (!this.setFillAmount(this._vBar, 1 - percent)) {
                    this._vBar.height = Math.round(fullHeight * percent);
                    this._vBar.y = this._barStartY + (fullHeight - this._vBar.height);
                }
            }
        }
    }

    private updateTitle(value: number, max: number, percent: number) {
        let obj = this._titleWidget;
        if (!obj)
            return;

        switch (this._titleType) {
            case ProgressTitleType.Percent:
                obj.text = Math.floor(percent * 100) + "%";
                break;

            case ProgressTitleType.ValueAndMax:
                obj.text = Math.floor(value) + "/" + Math.floor(max);
                break;

            case ProgressTitleType.Value:
                obj.text = "" + Math.floor(value);
                break;

            case ProgressTitleType.Max:
                obj.text = "" + Math.floor(max);
                break;
        }
    }

    private setFillAmount(bar: GWidget, amount: number): boolean {
        let mesh = (<GImage | GLoader>bar).mesh;
        if (mesh instanceof ProgressMesh) {
            mesh.amount = amount;
            bar.graphics.repaint();
            return true;
        }
        else
            return false;
    }

    /** @internal */
    _onConstruct(inPrefab?: boolean): void {
        if (this._hBar) {
            this._barMaxWidthDelta = this.width - this._hBar.width;
            this._barStartX = this._hBar.x;
        }
        if (this._vBar) {
            this._barMaxHeightDelta = this.height - this._vBar.height;
            this._barStartY = this._vBar.y;
        }
        ILaya.timer.runCallLater(this, this.update, true);

        super._onConstruct(inPrefab);
    }

    protected _sizeChanged(): void {
        super._sizeChanged();

        this.update(null, true);
    }
}
